export class PickupService {
  constructor(
    private readonly codes: PickupCodeRepository,
    private readonly reservations: ReservationRepository,
    private readonly lockers: LockerRepository
  ) {}

  async verify(reservationId: string, pickupCode: string) {
    const code = await this.codes.findByReservationId(reservationId);

    if (!code || code.usedAt) {
      throw new AppError(
        401,
        "INVALID_PICKUP_CODE",
        "Pickup code is invalid"
      );
    }

    if (code.lockedUntil && code.lockedUntil.getTime() > Date.now()) {
      throw new AppError(
        429,
        "PICKUP_ATTEMPT_LOCKED",
        "Pickup attempts are temporarily locked"
      );
    }

    if (code.code !== pickupCode) {
      await this.codes.incrementFailure(reservationId);
      throw new AppError(
        401,
        "INVALID_PICKUP_CODE",
        "Pickup code is invalid"
      );
    }

    const reservation = await this.reservations.findById(reservationId);
    if (!reservation) {
      throw new AppError(404, "RESERVATION_NOT_FOUND", "Reservation not found");
    }

    await this.codes.markUsed(reservationId);
    await this.lockers.updateStatus(
      reservation.lockerId,
      "OPEN_REQUESTED"
    );

    return { openRequested: true };
  }
}

