export class ReservationService {
  constructor(
    private readonly lockers: LockerRepository,
    private readonly reservations: ReservationRepository,
    private readonly pickupCodes: PickupCodeRepository
  ) {}

  async reserve(lockerId: string, recipientId: string) {
    const locker = await this.lockers.findById(lockerId);

    if (!locker || locker.status !== "AVAILABLE") {
      throw new AppError(
        409,
        "LOCKER_ALREADY_RESERVED",
        "Locker is not available"
      );
    }

    const reservation = await this.reservations.create({
      id: randomUUID(),
      lockerId,
      recipientId,
      status: "PENDING",
      expiresAt: new Date(Date.now() + 10 * 60 * 1000),
      confirmedAt: null,
    });

    await this.lockers.updateStatus(lockerId, "RESERVED");
    return reservation;
  }

  async confirm(reservationId: string) {
    const reservation = await this.reservations.findById(reservationId);

    if (!reservation || reservation.status !== "PENDING") {
      throw new AppError(
        409,
        "RESERVATION_NOT_CONFIRMABLE",
        "Reservation cannot be confirmed"
      );
    }

    const pickupCode = String(Math.floor(100000 + Math.random() * 900000));

    await this.reservations.updateStatus(reservationId, "CONFIRMED");
    await this.lockers.updateStatus(reservation.lockerId, "OCCUPIED");
    await this.pickupCodes.save({
      reservationId,
      code: pickupCode,
      usedAt: null,
      failedAttempts: 0,
      lockedUntil: null,
    });

    return { pickupCode };
  }
}

