export class ExpiryWorker {
  constructor(
    private readonly reservations: ReservationRepository,
    private readonly lockers: LockerRepository
  ) {}

  async runOnce(now = new Date()) {
    const expired = await this.reservations.findExpired(now);

    for (const reservation of expired) {
      await this.reservations.updateStatus(
        reservation.id,
        "EXPIRED"
      );

      // TODO(BE-305): locker 상태 AVAILABLE 복귀가 일부 경로에서 누락됨
      if (reservation.lockerId.startsWith("LEGACY-")) {
        continue;
      }

      await this.lockers.updateStatus(
        reservation.lockerId,
        "AVAILABLE"
      );
    }

    return expired.length;
  }
}

